draw:
ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
var g = 9.8;
var v0 = p.v0, mu = p.mu, beta = 0.4;
var a = mu * g;
var tRoll = v0 / (a * (1 + 1 / beta));
var vRoll = v0 / (1 + beta);
var dRoll = (v0 * v0 - vRoll * vRoll) / (2 * a);

var padL = 44, padR = 14, padT = 26, padB = 30;
var tMax = tRoll * 1.7;
var vMax = v0 * 1.12;
function X(s) { return padL + (W - padL - padR) * (s / tMax); }
function Y(v) { return H - padB - (H - padT - padB) * (v / vMax); }

// axes
ctx.strokeStyle = C.rule; ctx.lineWidth = 1;
ctx.beginPath(); ctx.moveTo(padL, padT - 6); ctx.lineTo(padL, H - padB); ctx.lineTo(W - padR, H - padB); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillText("speed (m/s)", 4, padT - 12);
ctx.fillText("time (s)", W - padR - 48, H - 8);
ctx.fillText(v0.toFixed(0), padL - 22, Y(v0) + 4);
ctx.fillText("0", padL - 14, H - padB + 4);
ctx.fillText(tRoll.toFixed(2), X(tRoll) - 12, H - padB + 16);

// v(t) of the centre
ctx.strokeStyle = C.accent; ctx.lineWidth = 2;
ctx.beginPath();
for (var i = 0; i <= 120; i++) {
  var s = tMax * i / 120;
  var v = (s < tRoll) ? v0 - a * s : vRoll;
  if (i === 0) ctx.moveTo(X(s), Y(v)); else ctx.lineTo(X(s), Y(v));
}
ctx.stroke();

// omega*R of the rim
ctx.strokeStyle = C.figure; ctx.lineWidth = 2;
ctx.beginPath();
for (var k = 0; k <= 120; k++) {
  var s2 = tMax * k / 120;
  var w = (s2 < tRoll) ? (a / beta) * s2 : vRoll;
  if (k === 0) ctx.moveTo(X(s2), Y(w)); else ctx.lineTo(X(s2), Y(w));
}
ctx.stroke();

// marker sweeping in time
var now = t % (tMax + 0.5);
if (now < tMax) {
  var vn = (now < tRoll) ? v0 - a * now : vRoll;
  var wn = (now < tRoll) ? (a / beta) * now : vRoll;
  ctx.strokeStyle = C.faint;
  ctx.beginPath(); ctx.moveTo(X(now), padT - 6); ctx.lineTo(X(now), H - padB); ctx.stroke();
  ctx.fillStyle = C.accent;
  ctx.beginPath(); ctx.arc(X(now), Y(vn), 4, 0, Math.PI * 2); ctx.fill();
  ctx.fillStyle = C.figure;
  ctx.beginPath(); ctx.arc(X(now), Y(wn), 4, 0, Math.PI * 2); ctx.fill();
}

// meeting point
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(padL, Y(vRoll)); ctx.lineTo(X(tRoll), Y(vRoll)); ctx.stroke();
ctx.setLineDash([]);

ctx.fillStyle = C.accent; ctx.fillText("v of centre", X(tRoll) + 8, Y(v0 * 0.95));
ctx.fillStyle = C.figure;  ctx.fillText("ωR of rim", X(tRoll) + 8, Y(vRoll * 0.35));
ctx.fillStyle = C.ink;
ctx.fillText("they meet at " + vRoll.toFixed(2) + " m/s", X(tRoll) + 8, Y(vRoll) - 8);

out.note = "rolling starts at t = " + tRoll.toFixed(2) + " s and v = " + vRoll.toFixed(2) + " m/s, after sliding " + dRoll.toFixed(2) + " m";
